insert into public.services (id, company_id, category_id, title_ar, title_en, description_ar, description_en, photos, position) values
  ('s1', 'c1', 0, 'بناء الفلل السكنية', 'Villa construction', 'تقدّم النور للمقاولات خدمة «بناء الفلل السكنية» لتسليم منزل العائلة جاهزًا من الأساسات حتى التشطيب. تشمل الخدمة استخراج التراخيص، وأعمال الهيكل الخرساني، والتمديدات، والتشطيبات، بإشراف مهندس موقع مخصص. يتولى فريقنا العمل من الزيارة الأولى والقياس حتى التسليم، مع متابعة بعد التنفيذ. تواصل معنا عبر واتساب أو الاتصال لمناقشة مشروعك.', 'Al Noor Contracting offers villa construction to hand over the family home ready, from foundations to finishing. The service covers permits, the concrete structure, services and finishes, with a dedicated site engineer. Our team handles it from the first visit and measurements to handover, with a follow-up afterwards. Message us on WhatsApp or call to discuss your project.', array['1504307651254-35680f356dfd','1541888946425-d81bb19240f5','1600585154340-be6161a56a0c']::text[], 0),
  ('s2', 'c1', 0, 'مراجعة التصاميم الإنشائية', 'Structural design review', 'تقدّم النور للمقاولات خدمة «مراجعة التصاميم الإنشائية» للتأكد من سلامة التصميم الإنشائي قبل البدء بالبناء. تشمل الخدمة مراجعة الحسابات والمخططات، وفحص تقرير التربة، واقتراح تعديلات توفّر في الحديد والخرسانة، وتقريرًا معتمدًا للمالك. نبدأ بزيارة للموقع لفهم احتياجك، ثم نقدم تصورًا وعرض سعر واضحًا قبل البدء. اطلب عرض سعر عبر واتساب، وتصفّح مشاريعنا المنجزة في الأسفل.', 'Al Noor Contracting offers structural design review to make sure the structural design is sound before building starts. The service covers checking calculations and drawings, reviewing the soil report, suggesting savings in steel and concrete, and a signed report for the owner. We start with a site visit to understand what you need, then share a plan and a clear quote before starting. Ask for a quote on WhatsApp, and browse our completed projects below.', array['1503387762-592deb58ef4e','1581092160562-40aa08e78837']::text[], 1),
  ('s3', 'c2', 4, 'تصميم المجالس', 'Majlis interior design', 'تقدّم ساحل للديكور خدمة «تصميم المجالس» لتجهيز مساحة ضيافة مريحة تجمع بين الطابع العُماني واللمسات العصرية. تشمل الخدمة تصميم الجلسات، واختيار الأقمشة والسجاد، والإضاءة المخفية، والستائر المتناسقة مع الجدران. نلتزم بجدول زمني متفق عليه، ونطلعك على سير العمل في كل مرحلة. يسعدنا الرد على استفساراتك عبر واتساب أو الاتصال.', 'Sahil Interiors offers majlis interior design to create a welcoming space that blends Omani character with modern touches. The service covers the seating, fabrics and rugs, hidden lighting, and curtains matched to the walls. We keep to an agreed schedule and keep you updated at every stage. We are happy to answer your questions on WhatsApp or by phone.', array['1615874959474-d609969a20ed','1600210492486-724fe5c67fb0','1618221195710-dd6b41faaea6']::text[], 2),
  ('s4', 'c2', 4, 'تجهيز داخلي متكامل', 'Full home interior fit-out', 'تقدّم ساحل للديكور خدمة «تجهيز داخلي متكامل» لتسليم المساحة جاهزة للسكن من الأرضيات حتى آخر قطعة أثاث. تشمل الخدمة الأرضيات والجدران والأسقف، والإضاءة، والأثاث المفصّل، والستائر والإكسسوارات، بإدارة مصمم واحد لكل التفاصيل. يتولى فريقنا العمل من الزيارة الأولى والقياس حتى التسليم، مع متابعة بعد التنفيذ. تواصل معنا عبر واتساب أو الاتصال لمناقشة مشروعك.', 'Sahil Interiors offers full home interior fit-out to hand over a space ready to live in, from the floors to the last piece of furniture. The service covers floors, walls and ceilings, lighting, made-to-measure furniture, curtains and accessories, with one designer managing every detail. Our team handles it from the first visit and measurements to handover, with a follow-up afterwards. Message us on WhatsApp or call to discuss your project.', array['1600607687939-ce8a6c25118c','1617104678098-de229db51175','1586023492125-27b2c045efd7']::text[], 3),
  ('s5', 'c3', 2, 'تحديث لوحات الكهرباء', 'Electrical panel upgrade', 'تقدّم برق للكهرباء خدمة «تحديث لوحات الكهرباء» لرفع قدرة اللوحة وحماية المنزل من الأحمال الزائدة. تشمل الخدمة فحص الأحمال، واستبدال اللوحة القديمة بلوحة حديثة، وتركيب قواطع حماية من التسرب الأرضي، وترقيم الدوائر بوضوح. نبدأ بزيارة للموقع لفهم احتياجك، ثم نقدم تصورًا وعرض سعر واضحًا قبل البدء. اطلب عرض سعر عبر واتساب، وتصفّح مشاريعنا المنجزة في الأسفل.', 'Barq Electric offers electrical panel upgrade to raise panel capacity and protect the home from overloads. The service covers a load survey, replacing the old panel with a modern one, earth-leakage protection and clearly labelled circuits. We start with a site visit to understand what you need, then share a plan and a clear quote before starting. Ask for a quote on WhatsApp, and browse our completed projects below.', array['1621905251189-08b45d6a269e','1621905252507-b35492cc74b4']::text[], 4),
  ('s7', 'c4', 9, 'تصميم وتركيب المطابخ', 'Kitchen design & installation', 'تقدّم قمة المطابخ خدمة «تصميم وتركيب المطابخ» ليكون المطبخ عمليًا وجميلًا ويناسب طريقة طبخ العائلة. تشمل الخدمة زيارة القياس، وتصميمًا ثلاثي الأبعاد، واختيار الخامات والأجهزة، ثم التصنيع والتركيب مع سطح العمل والإضاءة. نلتزم بجدول زمني متفق عليه، ونطلعك على سير العمل في كل مرحلة. يسعدنا الرد على استفساراتك عبر واتساب أو الاتصال.', 'Qimmah Kitchens offers kitchen design & installation to make a kitchen that is practical, beautiful and fits how the family cooks. The service covers a measuring visit, a 3D design, choosing materials and appliances, then manufacturing and fitting with worktop and lighting. We keep to an agreed schedule and keep you updated at every stage. We are happy to answer your questions on WhatsApp or by phone.', array['1484154218962-a197022b5858','1588854337236-6889d631faa8','1600566753190-17f0baa2a6c3']::text[], 5),
  ('s9', 'c5', 8, 'تصميم وتنفيذ الحدائق', 'Garden design & build', 'تقدّم حدائق الوادي خدمة «تصميم وتنفيذ الحدائق» لتحويل المساحة الخارجية إلى مكان مريح للجلوس واللعب. تشمل الخدمة التصميم، وتسوية التربة، والزراعة بنباتات تناسب مناخ عُمان، وشبكة الري، والممرات والإضاءة الخارجية. يتولى فريقنا العمل من الزيارة الأولى والقياس حتى التسليم، مع متابعة بعد التنفيذ. تواصل معنا عبر واتساب أو الاتصال لمناقشة مشروعك.', 'Wadi Gardens offers garden design & build to turn the outdoor space into a pleasant place to sit and play. The service covers design, ground levelling, planting suited to Oman''s climate, irrigation, paths and outdoor lighting. Our team handles it from the first visit and measurements to handover, with a follow-up afterwards. Message us on WhatsApp or call to discuss your project.', array['1558904541-efa843a96f01','1564013799919-ab600027ffc6','1416879595882-3373a0480b5b']::text[], 6),
  ('s11', 'c6', 6, 'تركيب كاميرات المراقبة', 'CCTV installation', 'تقدّم سراج للبيوت الذكية خدمة «تركيب كاميرات المراقبة» لتغطية كل المداخل والمساحات الحساسة على مدار الساعة. تشمل الخدمة دراسة زوايا التصوير، وتركيب كاميرات عالية الدقة، وجهاز تسجيل، وإعداد المشاهدة عبر الهاتف. نبدأ بزيارة للموقع لفهم احتياجك، ثم نقدم تصورًا وعرض سعر واضحًا قبل البدء. اطلب عرض سعر عبر واتساب، وتصفّح مشاريعنا المنجزة في الأسفل.', 'Siraj Smart Homes offers CCTV installation to cover every entrance and sensitive area around the clock. The service covers camera angles, high-resolution cameras, a recorder, and viewing from the phone. We start with a site visit to understand what you need, then share a plan and a clear quote before starting. Ask for a quote on WhatsApp, and browse our completed projects below.', array['1557597774-9d273605dfa9']::text[], 7),
  ('s12', 'c7', 1, 'تركيب المكيفات', 'AC installation', 'تقدّم برد للتكييف خدمة «تركيب المكيفات» لتوفير تبريد متوازن وهادئ في جميع المساحات. تشمل الخدمة حساب الأحمال الحرارية، واختيار الوحدات المناسبة، وتمديد الأنابيب والتصريف، ثم التشغيل والاختبار. نلتزم بجدول زمني متفق عليه، ونطلعك على سير العمل في كل مرحلة. يسعدنا الرد على استفساراتك عبر واتساب أو الاتصال.', 'Bard Cooling offers AC installation to deliver even, quiet cooling across every space. The service covers heat-load calculations, choosing the right units, piping and drainage, then commissioning and testing. We keep to an agreed schedule and keep you updated at every stage. We are happy to answer your questions on WhatsApp or by phone.', array['1545259741-2ea3ebf61fa3']::text[], 8),
  ('s13', 'c7', 1, 'صيانة المكيفات', 'AC maintenance', 'تقدّم برد للتكييف خدمة «صيانة المكيفات» لإعادة كفاءة التبريد وخفض استهلاك الكهرباء. تشمل الخدمة فحص الوحدات، وتنظيف المبخرات والفلاتر، وقياس ضغط الغاز، واستبدال القطع التالفة. يتولى فريقنا العمل من الزيارة الأولى والقياس حتى التسليم، مع متابعة بعد التنفيذ. تواصل معنا عبر واتساب أو الاتصال لمناقشة مشروعك.', 'Bard Cooling offers AC maintenance to restore cooling performance and cut power use. The service covers inspecting every unit, cleaning coils and filters, checking gas pressure and replacing worn parts. Our team handles it from the first visit and measurements to handover, with a follow-up afterwards. Message us on WhatsApp or call to discuss your project.', array['1545259741-2ea3ebf61fa3']::text[], 9),
  ('s17', 'c10', 6, 'مراقبة الفلل', 'Villa CCTV', 'تقدّم أمان للأنظمة الأمنية خدمة «مراقبة الفلل» لتأمين محيط الفيلا ومتابعتها من أي مكان. تشمل الخدمة تركيب كاميرات خارجية وداخلية، وجهاز تسجيل، وإعداد التنبيهات على الهاتف. نبدأ بزيارة للموقع لفهم احتياجك، ثم نقدم تصورًا وعرض سعر واضحًا قبل البدء. اطلب عرض سعر عبر واتساب، وتصفّح مشاريعنا المنجزة في الأسفل.', 'Amaan Security offers villa CCTV to secure the villa grounds and watch them from anywhere. The service covers outdoor and indoor cameras, a recorder and phone alerts. We start with a site visit to understand what you need, then share a plan and a clear quote before starting. Ask for a quote on WhatsApp, and browse our completed projects below.', array['1557597774-9d273605dfa9']::text[], 10),
  ('s18', 'c10', 7, 'أنظمة إنذار الحريق', 'Fire alarm systems', 'تقدّم أمان للأنظمة الأمنية خدمة «أنظمة إنذار الحريق» لحماية الأرواح والممتلكات وفق اشتراطات الدفاع المدني. تشمل الخدمة تصميم توزيع الكواشف، وتركيب لوحة الإنذار، وتمديد الكابلات المقاومة للحريق، واختبار النظام مع الجهات المختصة. نلتزم بجدول زمني متفق عليه، ونطلعك على سير العمل في كل مرحلة. يسعدنا الرد على استفساراتك عبر واتساب أو الاتصال.', 'Amaan Security offers fire alarm systems to protect people and property in line with civil defence requirements. The service covers detector layout, the alarm panel, fire-rated cabling, and system testing with the authorities. We keep to an agreed schedule and keep you updated at every stage. We are happy to answer your questions on WhatsApp or by phone.', array['1607472586893-edb57bdc0e39']::text[], 11),
  ('sg0-0-0', 'g0-0', 0, 'بناء الفلل', 'Villa construction', 'تقدّم الريادة للمقاولات خدمة «بناء الفلل» لتسليم منزل العائلة جاهزًا من الأساسات حتى التشطيب. تشمل الخدمة استخراج التراخيص، وأعمال الهيكل الخرساني، والتمديدات، والتشطيبات الداخلية والخارجية، بإشراف مهندس موقع مخصص. يتولى فريقنا العمل من الزيارة الأولى والقياس حتى التسليم، مع متابعة بعد التنفيذ. تواصل معنا عبر واتساب أو الاتصال لمناقشة مشروعك.', 'Al Riyada Contracting offers villa construction to hand over the family home ready, from foundations to finishing. The service covers permits, the concrete structure, services, and interior and exterior finishes, with a dedicated site engineer. Our team handles it from the first visit and measurements to handover, with a follow-up afterwards. Message us on WhatsApp or call to discuss your project.', array['1504307651254-35680f356dfd','1541888946425-d81bb19240f5']::text[], 12),
  ('sg0-0-1', 'g0-0', 0, 'ملاحق ومجالس خارجية', 'Annexes & outdoor majlis', 'تقدّم الريادة للمقاولات خدمة «ملاحق ومجالس خارجية» لإضافة مساحة ضيافة منفصلة عن المنزل الرئيسي. تشمل الخدمة التصميم والترخيص، والبناء، والعزل الحراري، والتمديدات، والتشطيبات بما يتناسب مع واجهة المنزل. نبدأ بزيارة للموقع لفهم احتياجك، ثم نقدم تصورًا وعرض سعر واضحًا قبل البدء. اطلب عرض سعر عبر واتساب، وتصفّح مشاريعنا المنجزة في الأسفل.', 'Al Riyada Contracting offers annexes & outdoor majlis to add a guest space separate from the main house. The service covers design and permits, construction, insulation, services and finishes that match the house. We start with a site visit to understand what you need, then share a plan and a clear quote before starting. Ask for a quote on WhatsApp, and browse our completed projects below.', array['1541888946425-d81bb19240f5','1600585154340-be6161a56a0c']::text[], 13),
  ('sg0-1-0', 'g0-1', 0, 'بناء الفلل', 'Villa construction', 'تقدّم الإتقان للمقاولات خدمة «بناء الفلل» لتسليم منزل العائلة جاهزًا من الأساسات حتى التشطيب. تشمل الخدمة استخراج التراخيص، وأعمال الهيكل الخرساني، والتمديدات، والتشطيبات الداخلية والخارجية، بإشراف مهندس موقع مخصص. نلتزم بجدول زمني متفق عليه، ونطلعك على سير العمل في كل مرحلة. يسعدنا الرد على استفساراتك عبر واتساب أو الاتصال.', 'Al Itqan Contracting offers villa construction to hand over the family home ready, from foundations to finishing. The service covers permits, the concrete structure, services, and interior and exterior finishes, with a dedicated site engineer. We keep to an agreed schedule and keep you updated at every stage. We are happy to answer your questions on WhatsApp or by phone.', array['1541888946425-d81bb19240f5','1600585154340-be6161a56a0c']::text[], 14),
  ('sg0-1-1', 'g0-1', 0, 'ملاحق ومجالس خارجية', 'Annexes & outdoor majlis', 'تقدّم الإتقان للمقاولات خدمة «ملاحق ومجالس خارجية» لإضافة مساحة ضيافة منفصلة عن المنزل الرئيسي. تشمل الخدمة التصميم والترخيص، والبناء، والعزل الحراري، والتمديدات، والتشطيبات بما يتناسب مع واجهة المنزل. يتولى فريقنا العمل من الزيارة الأولى والقياس حتى التسليم، مع متابعة بعد التنفيذ. تواصل معنا عبر واتساب أو الاتصال لمناقشة مشروعك.', 'Al Itqan Contracting offers annexes & outdoor majlis to add a guest space separate from the main house. The service covers design and permits, construction, insulation, services and finishes that match the house. Our team handles it from the first visit and measurements to handover, with a follow-up afterwards. Message us on WhatsApp or call to discuss your project.', array['1600585154340-be6161a56a0c','1449844908441-8829872d2607']::text[], 15),
  ('sg0-2-0', 'g0-2', 0, 'بناء الفلل', 'Villa construction', 'تقدّم الجبل الأخضر للمقاولات خدمة «بناء الفلل» لتسليم منزل العائلة جاهزًا من الأساسات حتى التشطيب. تشمل الخدمة استخراج التراخيص، وأعمال الهيكل الخرساني، والتمديدات، والتشطيبات الداخلية والخارجية، بإشراف مهندس موقع مخصص. نبدأ بزيارة للموقع لفهم احتياجك، ثم نقدم تصورًا وعرض سعر واضحًا قبل البدء. اطلب عرض سعر عبر واتساب، وتصفّح مشاريعنا المنجزة في الأسفل.', 'Green Mountain Contracting offers villa construction to hand over the family home ready, from foundations to finishing. The service covers permits, the concrete structure, services, and interior and exterior finishes, with a dedicated site engineer. We start with a site visit to understand what you need, then share a plan and a clear quote before starting. Ask for a quote on WhatsApp, and browse our completed projects below.', array['1600585154340-be6161a56a0c','1449844908441-8829872d2607']::text[], 16),
  ('sg0-2-1', 'g0-2', 0, 'ملاحق ومجالس خارجية', 'Annexes & outdoor majlis', 'تقدّم الجبل الأخضر للمقاولات خدمة «ملاحق ومجالس خارجية» لإضافة مساحة ضيافة منفصلة عن المنزل الرئيسي. تشمل الخدمة التصميم والترخيص، والبناء، والعزل الحراري، والتمديدات، والتشطيبات بما يتناسب مع واجهة المنزل. نلتزم بجدول زمني متفق عليه، ونطلعك على سير العمل في كل مرحلة. يسعدنا الرد على استفساراتك عبر واتساب أو الاتصال.', 'Green Mountain Contracting offers annexes & outdoor majlis to add a guest space separate from the main house. The service covers design and permits, construction, insulation, services and finishes that match the house. We keep to an agreed schedule and keep you updated at every stage. We are happy to answer your questions on WhatsApp or by phone.', array['1449844908441-8829872d2607','1503387762-592deb58ef4e']::text[], 17),
  ('sg0-3-0', 'g0-3', 0, 'بناء الفلل', 'Villa construction', 'تقدّم المسار للمقاولات خدمة «بناء الفلل» لتسليم منزل العائلة جاهزًا من الأساسات حتى التشطيب. تشمل الخدمة استخراج التراخيص، وأعمال الهيكل الخرساني، والتمديدات، والتشطيبات الداخلية والخارجية، بإشراف مهندس موقع مخصص. يتولى فريقنا العمل من الزيارة الأولى والقياس حتى التسليم، مع متابعة بعد التنفيذ. تواصل معنا عبر واتساب أو الاتصال لمناقشة مشروعك.', 'Al Masar Contracting offers villa construction to hand over the family home ready, from foundations to finishing. The service covers permits, the concrete structure, services, and interior and exterior finishes, with a dedicated site engineer. Our team handles it from the first visit and measurements to handover, with a follow-up afterwards. Message us on WhatsApp or call to discuss your project.', array['1449844908441-8829872d2607','1503387762-592deb58ef4e']::text[], 18),
  ('sg0-3-1', 'g0-3', 0, 'ملاحق ومجالس خارجية', 'Annexes & outdoor majlis', 'تقدّم المسار للمقاولات خدمة «ملاحق ومجالس خارجية» لإضافة مساحة ضيافة منفصلة عن المنزل الرئيسي. تشمل الخدمة التصميم والترخيص، والبناء، والعزل الحراري، والتمديدات، والتشطيبات بما يتناسب مع واجهة المنزل. نبدأ بزيارة للموقع لفهم احتياجك، ثم نقدم تصورًا وعرض سعر واضحًا قبل البدء. اطلب عرض سعر عبر واتساب، وتصفّح مشاريعنا المنجزة في الأسفل.', 'Al Masar Contracting offers annexes & outdoor majlis to add a guest space separate from the main house. The service covers design and permits, construction, insulation, services and finishes that match the house. We start with a site visit to understand what you need, then share a plan and a clear quote before starting. Ask for a quote on WhatsApp, and browse our completed projects below.', array['1503387762-592deb58ef4e','1504307651254-35680f356dfd']::text[], 19),
